INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Mesin tidak menjalankan siklus buttonhole', 'Mesin tidak memulai siklus pembuatan lubang kancing atau berhenti sebelum jahitan selesai.', 'Catu daya, control box, pengaturan pola, pedal, atau sistem penggerak mengalami gangguan.', 'Periksa sumber listrik, koneksi control box, pemilihan pola, dan kondisi pedal. Pastikan pengaturan pola sesuai sebelum menjalankan siklus kembali.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa koneksi listrik atau control box.', 'Panduan pemeriksaan umum JUKI LBH-1790AN');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Benang jarum sering putus', 'Benang jarum putus berulang selama proses pembuatan lubang kancing.', 'Jarum DP×5 tidak sesuai, jarum bengkok atau tumpul, jalur benang kurang tepat, atau tegangan benang terlalu tinggi.', 'Periksa jalur benang dan tegangan. Gunakan jarum DP×5 yang sesuai dan ganti jika bengkok atau tumpul.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyesuaian pada area jarum.', 'Data spesifikasi jarum JUKI LBH-1790AN dan panduan troubleshooting umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Lubang kancing tidak terpotong dengan benar', 'Hasil pemotongan lubang kancing tidak sesuai ukuran atau potongan tidak bersih.', 'Cloth cutting knife tidak sesuai, kondisi pisau kurang baik, atau pengaturan panjang lubang kancing tidak sesuai.', 'Periksa kondisi dan ukuran cloth cutting knife. Pastikan pengaturan panjang lubang kancing sesuai dengan kebutuhan material.', 'Matikan mesin sebelum memeriksa atau mengganti pisau pemotong.', 'Data spesifikasi cloth cutting knife JUKI LBH-1790AN');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Panjang lubang kancing tidak sesuai', 'Panjang buttonhole aktual berbeda dari ukuran yang diprogram.', 'Pengaturan pola atau parameter panjang tidak sesuai, atau mekanisme feeding mengalami gangguan.', 'Periksa parameter pola dan panjang buttonhole. LBH-1790AN memiliki panjang buttonhole standar maksimum 41 mm, dengan opsi tertentu untuk ukuran lebih panjang.', 'Matikan mesin sebelum melakukan pemeriksaan mekanisme feeding.', 'Data spesifikasi buttonhole length JUKI LBH-1790AN');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Pola buttonhole tidak sesuai', 'Bentuk atau jenis jahitan lubang kancing tidak sesuai pola yang dipilih.', 'Pola yang dipilih tidak tepat, data pola bermasalah, atau pengaturan pattern input tidak sesuai.', 'Periksa pattern yang dipilih dan parameter jahitan. Pastikan pola yang digunakan sesuai dengan kebutuhan produksi.', 'Hentikan mesin sebelum mengubah atau memeriksa pengaturan pola.', 'Data spesifikasi standard patterns dan input patterns JUKI LBH-1790AN');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Jahitan lubang kancing tidak rapi atau loncat', 'Jahitan buttonhole tidak konsisten, terdapat bagian yang terlewat, atau bentuk jahitan tidak rapi.', 'Jarum tidak sesuai, hook atau timing mengalami gangguan, atau material tidak terposisikan dengan benar.', 'Periksa jarum DP×5, posisi material, dan kondisi hook. Jika timing hook perlu disetel, lakukan pemeriksaan oleh teknisi.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa jarum atau hook.', 'Data spesifikasi hook dan jarum JUKI LBH-1790AN serta panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Presser foot tidak mengangkat dengan baik', 'Presser foot sulit terangkat atau posisi angkat tidak sesuai.', 'Mekanisme presser foot mengalami hambatan atau penyetelan tidak tepat.', 'Periksa mekanisme presser foot dan pastikan gerakannya bebas. Spesifikasi lift presser foot LBH-1790AN adalah 14 mm.', 'Matikan mesin sebelum melakukan pemeriksaan atau penyetelan mekanisme presser foot.', 'Data spesifikasi presser foot lift JUKI LBH-1790AN');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (6, 'Motor atau sistem penggerak tidak normal', 'Putaran mesin tidak stabil, mesin berhenti saat siklus berjalan, atau respons penggerak tidak normal.', 'Gangguan pada compact AC servomotor, koneksi listrik, control box, atau sistem direct-drive.', 'Periksa koneksi motor dan control box. Pastikan tidak ada hambatan mekanis pada sistem direct-drive. Jika gangguan berlanjut, lakukan pemeriksaan oleh teknisi.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa motor, control box, atau sistem penggerak.', 'Data spesifikasi drive system JUKI LBH-1790AN dan panduan pemeriksaan umum');
